function moon(c,x,y,r){c.fillStyle='#c0b1ca';c.fillRect(x-r+4,y-r,r*2-8,r*2);c.fillRect(x-r,y-r+4,r*2,r*2-8);c.fillStyle='#b3a5c1';c.fillRect(x+1,y-r+7,8,5);c.fillRect(x-9,y+2,5,8);c.fillStyle='#cfc2d6';c.fillRect(x-6,y-r+3,7,3)}
function bamboo(c,width,height,offset=0,mini=false){let s=mini?.5:1;for(let layer=0;layer<2;layer++){for(let i=0;i<9;i++){let x=((i*67+layer*29)%(width+50))-25,y=height-(110+((i*43)%130))*s; c.fillStyle=layer?'#202c3d':'#1b2136';c.fillRect(x,y,5*s,height-y);for(let j=0;j<7;j++){let yy=y+j*31*s+(offset%(31*s));c.fillStyle=layer?'#344051':'#252c42';c.fillRect(x-1,yy,7*s,2*s);c.fillStyle=layer?'#25354a':'#20283e';for(let k=0;k<3;k++){c.fillRect(x-(15+k*5)*s,yy-(12-k*3)*s,(16-k*2)*s,3*s);c.fillRect(x+4*s,yy-(19-k*4)*s,(20-k*3)*s,3*s)}}}}}
function background(c,w,h,t,mini=false){c.fillStyle='#111425';c.fillRect(0,0,w,h);c.fillStyle='#181b30';for(let i=0;i<7;i++)c.fillRect(0,h*.25+i*18,w,10);let sx=w/480,sy=h/640;stars.forEach(a=>{c.globalAlpha=a.a;c.fillStyle='#c4bad8';c.fillRect(Math.floor(a.x*sx),Math.floor(((a.y+t*a.speed*14)%640)*sy),a.s,a.s)});c.globalAlpha=1;moon(c,w*.73,h*.22,mini?17:30);c.fillStyle='#1d2237';for(let i=0;i<12;i++){let x=i*w/10;c.fillRect(x,h*.56-Math.sin(i*1.4)*25,w/10+1,h*.44+25)}bamboo(c,w,h,t*3,mini);c.fillStyle='#151a2e';c.fillRect(w*.48,h*.49,mini?5:8,h*.27);c.fillRect(w*.72,h*.49,mini?5:8,h*.27);c.fillStyle='#55405b';c.fillRect(w*.45,h*.48,w*.32,mini?4:6);c.fillRect(w*.47,h*.53,w*.28,mini?3:4);c.fillStyle='#8b5577';c.fillRect(w*.44,h*.475,w*.34,mini?2:3);c.fillStyle='#0e1525';c.fillRect(0,h*.94,w,h*.06);petals.forEach(p=>{let x=(p.x+Math.sin(t*.5+p.phase)*30+t*5)%W,y=(p.y+t*17)%H;c.fillStyle='#d48dac';c.globalAlpha=.4;c.fillRect(x*sx,y*sy,p.s+1,p.s);c.fillRect(x*sx+1,y*sy-1,1,1)});c.globalAlpha=1}
