function start(){mode='playing';time=0;score=0;graze=0;lives=3;bombs=3;player={x:240,y:535};bullets=[];shots=[];enemies=[];particles=[];pickups=[];boss=null;spawnTimer=.5;shotTimer=0;invincible=2;bombFlash=0;$('#overlay').hidden=true;$('#bossbar').hidden=true;$('#mission1').textContent='○';$('#mission2').textContent='○';$('#status').textContent='SYSTEM ACTIVE';$('#stage-top').textContent='STAGE 01';$('#pause').textContent='Ⅱ PAUSE';hud();announce('星降る竹林','STAGE 01 · NIGHTFALL',2.6);tone(660,.3,'triangle')}
