function addEnemy(){let type=Math.floor(rand(0,3));enemies.push({x:rand(48,432),y:-30,hp:type===2?16:9,type,t:0,fire:rand(.6,1.2),base:rand(0,7)})}
function spawnBoss(){boss={x:240,y:-50,hp:1000,max:1000,t:0,fire:0,fan:1.3};bullets=[];$('#bossbar').hidden=false;$('#mission1').textContent='✓';$('#stage-top').textContent='BOSS BATTLE';announce('月影ノ蝶','LUNAR MOTH · THE BOUNDARY KEEPER',3);tone(180,.8,'triangle')}
