for(let e of enemies){e.t+=dt;e.y+=dt*(e.type===2?28:45);e.x+=Math.sin(e.t*2+e.base)*dt*25;e.fire-=dt;if(e.fire<0){let aim=Math.atan2(player.y-e.y,player.x-e.x),factor=level==='easy'?.7:level==='hard'?1.3:1;if(e.type===2)ring(e.x,e.y,level==='easy'?9:14,68*factor,e.t*.4,'#ffc078');else for(let i=-1;i<=1;i++)bullet(e.x,e.y,aim+i*.21,90*factor,'#f59cc9',4);e.fire=e.type===2?1.65:1.45}if(e.hp<=0){burst(e.x,e.y,'#f7a5d1',20);score+=500;pickups.push({x:e.x,y:e.y,t:0});e.dead=true;tone(300,.09,'square',.02)}}enemies=enemies.filter(e=>!e.dead&&e.y<H+30);
if(boss){boss.t+=dt;boss.x=240+Math.sin(boss.t*.65)*105;boss.y=Math.min(148,boss.y+dt*65);boss.fire-=dt;boss.fan-=dt;let factor=level==='easy'?.75:level==='hard'?1.18:1;if(boss.y>=100&&boss.fire<=0){let phase=boss.t*(boss.hp<500?.9:.45);ring(boss.x,boss.y,level==='easy'?14:20,(boss.hp<500?95:75)*factor,phase,boss.hp<500?'#f8b98d':'#f595c9');boss.fire=boss.hp<500?.56:.85}if(boss.y>=100&&boss.fan<=0){let aim=Math.atan2(player.y-boss.y,player.x-boss.x);for(let i=-3;i<=3;i++)bullet(boss.x,boss.y,aim+i*.14,135*factor,'#ffd477',3);boss.fan=1.8}if(boss.hp<=0){burst(boss.x,boss.y,'#ffd4ed',120);bullets=[];score+=20000;shake=12;hud();finish(true);return}}
