if(['playing','paused'].includes(mode)){if(invincible<=0||Math.floor(world*15)%2===0)drawSprite(ctx,player.x,player.y,2);ctx.fillStyle='#97e1d8';ctx.fillRect(player.x-9,player.y+15,3,rand(3,10));ctx.fillRect(player.x+6,player.y+15,3,rand(3,10));if(keys.has('Shift')||focusTouch){ctx.strokeStyle='#a3f7e4aa';ctx.beginPath();ctx.arc(player.x,player.y,12,0,7);ctx.stroke();ctx.fillStyle='#fff';ctx.fillRect(player.x-2,player.y-2,4,4);ctx.fillStyle='#20ddff';ctx.fillRect(player.x-1,player.y-1,2,2)}}
