function frame(now){let dt=Math.min((now-last)/1000||0,.033);last=now;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
$('#start').addEventListener('click',()=>{if(mode==='paused')pause();else{$('.difficulty').style.visibility='visible';start()}});$('#pause').addEventListener('click',pause);$('#sound').addEventListener('click',()=>{muted=!muted;$('#sound span').textContent=muted?'SOUND OFF':'SOUND ON';$('#sound').setAttribute('aria-label',muted?'サウンドをオンにする':'サウンドをオフにする');if(!muted)tone(600,.15,'triangle')});document.querySelectorAll('[data-level]').forEach(b=>b.addEventListener('click',()=>{level=b.dataset.level;document.querySelectorAll('[data-level]').forEach(a=>a.classList.toggle('selected',a===b))}));
