canvas.addEventListener('pointerdown',e=>{if(mode!=='playing')return;mobile=true;canvas.setPointerCapture(e.pointerId);let r=canvas.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,px:player.x,py:player.y,scale:W/r.width}});canvas.addEventListener('pointermove',e=>{if(!drag||mode!=='playing')return;player.x=clamp(drag.px+(e.clientX-drag.x)*drag.scale,15,W-15);player.y=clamp(drag.py+(e.clientY-drag.y)*drag.scale,80,H-30)});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);$('#touch-bomb').addEventListener('click',bomb);$('#touch-focus').addEventListener('pointerdown',e=>{e.preventDefault();focusTouch=true});window.addEventListener('pointerup',()=>focusTouch=false);
